var e={knownGoodPack:{intro:{t:0,b:{t:2,i:[{t:3}],s:`अपने काम कर रहे प्रिंटर कॉन्फ़िग को एक पैक के रूप में स्नैपशॉट करें, जिसे आप किसी ख़राब एडिट के बाद पुनर्स्थापित कर सकते हैं।`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`रद्द करें`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`अभी तक कोई पैक नहीं। जब आपका प्रिंटर आपकी पसंद के अनुसार कॉन्फ़िगर हो, तब एक बनाएँ।`}},files:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` कॉन्फ़िग फ़ाइलें`}]}},create:{label:{t:0,b:{t:2,i:[{t:3}],s:`नया पैक`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`जैसे, काम कर रहा SV08 - ट्यूनिंग से पहले`}},button:{t:0,b:{t:2,i:[{t:3}],s:`पैक बनाएँ`}}},restore:{button:{t:0,b:{t:2,i:[{t:3}],s:`पुनर्स्थापित करें`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`मौजूदा कॉन्फ़िग को इस पैक से बदलें?`}},note:{t:0,b:{t:2,i:[{t:3}],s:`पुनर्स्थापना आपकी कॉन्फ़िग फ़ाइलों को ओवरराइट कर देती है; लागू करने के लिए बाद में Klipper को रीस्टार्ट करें।`}},restored:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` कॉन्फ़िग फ़ाइलें पुनर्स्थापित कीं - लागू करने के लिए Klipper को रीस्टार्ट करें`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`प्रिंटर व्यस्त है - अभी पुनर्स्थापित नहीं किया जा सकता`}},not_found:{t:0,b:{t:2,i:[{t:3}],s:`पैक फ़ाइलें गायब हैं`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`इस पैक में कोई फ़ाइल नहीं है`}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:`पुनर्स्थापित नहीं किया जा सका: `},{t:4,k:`error`}]}}},delete:{button:{t:0,b:{t:2,i:[{t:3}],s:`हटाएँ`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`पैक हटाएँ`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`गाइड`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Known-Good Packs गाइड`}},close:{t:0,b:{t:2,i:[{t:3}],s:`बंद करें`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Known-Good Pack क्या है?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`हर प्रिंटर कॉन्फ़िग फ़ाइल (printer.cfg और उसके इन्क्लूड) का एक स्नैपशॉट, जिसे नामित पैक के रूप में सहेजा जाता है। जब आपका प्रिंटर अच्छे से प्रिंट करे, तब एक पैक कैप्चर कर लें, ताकि बाद का कोई एडिट कुछ ख़राब कर दे तो आप वापस लौट सकें।`}}},restore:{title:{t:0,b:{t:2,i:[{t:3}],s:`एक पैक पुनर्स्थापित करना`}},body:{t:0,b:{t:2,i:[{t:3}],s:`पुनर्स्थापना पैक की फ़ाइलों को आपके मौजूदा कॉन्फ़िग के ऊपर लिख देती है। प्रिंटर व्यस्त होने पर इसे अस्वीकार कर दिया जाता है, और पुनर्स्थापित कॉन्फ़िग को प्रभावी होने के लिए आपको बाद में Klipper को रीस्टार्ट करना होगा।`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`शब्दावली`}}}},glossary:{configPack:{term:{t:0,b:{t:2,i:[{t:3}],s:`कॉन्फ़िग पैक`}},def:{t:0,b:{t:2,i:[{t:3}],s:`एक समय बिंदु पर आपकी सभी प्रिंटर कॉन्फ़िग फ़ाइलों का सहेजा हुआ बंडल।`}}},restorePoint:{term:{t:0,b:{t:2,i:[{t:3}],s:`पुनर्स्थापना बिंदु`}},def:{t:0,b:{t:2,i:[{t:3}],s:`एक known-good स्थिति जहाँ आप लौट सकते हैं - यहाँ, प्रिंटर के काम कर रहे होने पर कैप्चर किया गया एक पैक।`}}}}}}};export{e as default};